#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int r,c;vector<string>g;string w;
bool dfs(int i,int j,int k){
if(k==(int)w.size())return true;
if(i<0||i>=r||j<0||j>=c||g[i][j]!=w[k])return false;
char t=g[i][j];g[i][j]='#';
bool ok=dfs(i+1,j,k+1)||dfs(i-1,j,k+1)||dfs(i,j+1,k+1)||dfs(i,j-1,k+1);
g[i][j]=t;return ok;}
int main(){scanf("%d %d",&r,&c);g.resize(r);
for(int i=0;i<r;++i)cin>>g[i];
cin>>w;
for(int i=0;i<r;++i)for(int j=0;j<c;++j)
if(dfs(i,j,0)){printf("YES\n");return 0;}
printf("NO\n");return 0;}

